export const ADMIN_JS = "'use strict';\n(()=>{\n const $=id=>document.getElementById(id);\n const TITLES={overview:['운영 대시보드','문의·오류·사용 현황을 빠르게 확인합니다.'],visits:['방문·사용 현황','사람 수가 아닌 비식별 브라우저 세션 기준입니다.'],diagnostics:['오류·작업 진단','파일명이나 PDF 내용 없이 오류 코드·처리 단계를 추적합니다.'],inquiries:['고객 문의','개인정보가 포함된 문의는 관리자 인증 후에만 조회합니다.'],publications:['공지·업데이트','최초 게시일 기준 7일 KST 표시 원칙을 적용합니다.'],system:['시스템·배포','관찰되지 않은 배포 상태는 미확인으로 표시합니다.'],security:['보안·세션','관리자 접근·세션·비밀번호 및 30일 보존 정책을 관리합니다.']};\n let csrf='',page='',loaded=null,selected=null;\n const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined&&text!==null)n.textContent=String(text);if(cls)n.className=cls;return n;};\n const append=(p,...nodes)=>{for(const n of nodes)if(n)p.append(n);return p;};\n const fmt=s=>s==null||s===''?'미확인':String(s);\n const dt=n=>n?new Date(n*1000).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',hour12:false}):'—';\n const headline=(name)=>{const [title,sub]=TITLES[name]||TITLES.overview;$('page-title').textContent=title;$('page-subtitle').textContent=sub;};\n function message(s,isError=false){$('feedback').textContent=s;$('feedback').classList.toggle('error',isError);}\n async function request(path,opts={}){\n  const headers={'Accept':'application/json',...(opts.headers||{})};\n  if(opts.method&&opts.method!=='GET'){headers['X-Sunrise-CSRF']=csrf;if(opts.body)headers['Content-Type']='application/json';}\n  const r=await fetch(path,{...opts,headers,cache:'no-store',credentials:'same-origin'});\n  let out={};try{out=await r.json();}catch{}\n  if(!r.ok)throw Error(out.error||'HTTP_'+r.status);\n  return out;\n }\n function box(title,...content){const p=el('section',null,'panel');append(p,el('h2',title),...content);return p;}\n function metric(label,value,unit=''){const p=el('div',null,'metric');append(p,el('small',label),el('strong',value),el('em',unit));return p;}\n function table(headers,rows){const wrap=el('div',null,'table-scroll'),t=el('table'),head=el('thead'),hr=el('tr');for(const h of headers)hr.append(el('th',h));head.append(hr);const body=el('tbody');if(!rows.length){const tr=el('tr'),cell=el('td','데이터 없음','empty');cell.colSpan=headers.length;tr.append(cell);body.append(tr);}for(const row of rows){const tr=el('tr');for(const item of row)tr.append(el('td',fmt(item)));body.append(tr);}t.append(head,body);wrap.append(t);return wrap;}\n function exportCsv(filename,headers,rows){\n  const quote=v=>'\"'+String(v??'').replaceAll('\"','\"\"')+'\"';\n  const csv='\\ufeff'+[headers,...rows].map(row=>row.map(quote).join(',')).join('\\r\\n');\n  const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));\n  const a=el('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();\n  setTimeout(()=>URL.revokeObjectURL(url),30000);\n }\n function line(k,v){const p=el('div',null,'status-card');append(p,el('b',k),el('span',fmt(v)));return p;}\n function field(label,value='',type='text'){const outer=el('label',null,'field');outer.append(el('span',label));const input=el(type==='textarea'?'textarea':'input');if(type!=='textarea')input.type=type;input.value=value||'';outer.append(input);return {outer,input};}\n function btn(text,fn,kind=''){const b=el('button',text,kind);b.type='button';b.addEventListener('click',fn);return b;}\n function root(...children){const target=$('page-root');target.replaceChildren(...children);}\n async function overview(){const d=await request('/api/admin/dashboard');const m=el('div',null,'metrics');append(m,\n metric('확인 전 문의',d.inquiries.new||0,'건'),metric('처리 중 문의',d.inquiries.in_progress||0,'건'),metric('오늘 기능 실패',d.failures_today,'건'),\n metric('오늘 방문 세션',d.visits_today,'개'),metric('오늘 활성 사용시간',Math.round(d.active_seconds_today/60),'분 · 추정'),metric('최근 7일 방문 세션',d.visits_7d,'개'),\n metric('오늘 변환 시작',d.started_today,'건'),metric('오늘 완료 이벤트',d.successes_today,'건'),metric('발행 상태 게시물',d.published,'건'));\n const errors=table(['오류 코드','처리 단계','최근 7일 건수'],(d.top_errors||[]).map(x=>[x.error_code,x.stage,x.n]));\n root(el('div','주의: 이 수치는 브라우저에서 서버로 전달된 비식별 이벤트 집계이며, 실제 문서 변환 성공률의 독립 검증 결과가 아닙니다.','notice'),m,box('자주 발생한 오류',errors)); }\n async function visits(){const d=await request('/api/admin/visits?days=14');root(el('div','방문 = 브라우저에서 생성한 임시 세션, 활성시간 = 30초 활동 신호 누적 추정치.','notice'),box('최근 14일 사용 추이',table(['KST 일자','방문 세션','활성시간(초)','변환 시작','완료','실패'],(d.rows||[]).map(x=>[new Date((x.kst_day*86400-32400)*1000).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul'}),x.visit_sessions||0,x.active_seconds||0,x.starts||0,x.successes||0,x.failures||0]))));}\n async function diagnostics(){const d=await request('/api/admin/diagnostics');const list=table(['원인 코드','처리 단계','기능','30일 건수'],(d.by_reason||[]).map(x=>[x.error_code,x.stage,x.feature,x.n]));const detail=table(['발생 시각(KST)','종류','기능','단계','상세 원인','시간(ms)','세션 ID'],(d.records||[]).map(x=>[dt(x.happened_at),x.event_kind,x.feature,x.stage,x.error_code,x.duration_ms,x.session_id.slice(0,8)]));const active=table(['비식별 세션','활성시간(초)'],(d.active_sessions||[]).map(x=>[x.session_id.slice(0,8),x.active_seconds]));\n const outcome=table(['종류','최근 7일 건수'],(d.outcomes||[]).map(x=>[x.event_kind,x.n]));\n const workflows=table(['발생 시각','작업 종류','기능','단계','오류 코드','소요시간(ms)'],(d.workflows||[]).map(x=>[dt(x.happened_at),x.event_kind,x.feature,x.stage,x.error_code,x.duration_ms]));\n const exportBar=el('div',null,'toolbar');\n exportBar.append(btn('오류 상세 CSV 내보내기',()=>exportCsv('sunrise-pro-error-diagnostics.csv',\n  ['시각(KST)','이벤트','기능','단계','오류 코드','소요시간(ms)','익명 세션 앞 8자리'],\n  (d.records||[]).map(x=>[dt(x.happened_at),x.event_kind,x.feature,x.stage,x.error_code,x.duration_ms,x.session_id.slice(0,8)]))));\n root(el('div','오류 건수만 집계하지 않고 원인 코드·발생 단계·익명 세션·처리 시간을 분리합니다. 파일명·문서 본문·스택은 수집하지 않습니다.','notice'),exportBar,box('① 실패 원인별 집계',list),box('② 개별 오류 세션',detail),box('③ 활성 사용시간 (7일)',active),box('④ 작업 성공·실패 집계',outcome),box('⑤ 최근 변환 흐름',workflows));}\n async function inquiries(){const d=await request('/api/admin/inquiries');const items=d.items||[];const wrap=el('div',null,'details-grid');const left=el('div',null,'select-list'),right=el('div',null,'stack');const draw=()=>{\n  left.replaceChildren();if(!items.length)left.append(el('div','등록된 문의가 없습니다.','empty'));\n  items.forEach(item=>{const b=el('button',item.subject);b.type='button';b.setAttribute('aria-pressed',String(selected===item.id));b.append(el('small',item.status+' · '+dt(item.created_at)));b.addEventListener('click',()=>{selected=item.id;draw();});left.append(b);});\n  right.replaceChildren();const item=items.find(x=>x.id===selected)||items[0];if(!item){right.append(el('div','문의를 선택하세요.'));return;}\n  selected=item.id;right.append(line('접수 시각',dt(item.created_at)),line('회신 이메일',item.email),line('제목',item.subject),line('문의 내용',item.message));\n  const state=el('select');for(const [v,t] of [['new','미확인'],['in_progress','처리 중'],['resolved','완료']]){const op=el('option',t);op.value=v;state.append(op);}state.value=item.status;\n  const note=field('관리자 메모',item.admin_note,'textarea');const s=el('div',null,'field');append(s,el('span','처리 상태'),state);\n  right.append(s,note.outer,btn('처리 상태 저장',async()=>{try{await request('/api/admin/inquiries/'+encodeURIComponent(item.id),{method:'PATCH',body:JSON.stringify({status:state.value,admin_note:note.input.value})});message('문의 처리 이력을 저장했습니다.');await inquiries();}catch(e){message(e.message,true);}},'primary'));\n };draw();wrap.append(left,right);root(box('문의 목록 · 최근 150건',wrap));}\n async function publications(){const d=await request('/api/admin/publications');const items=d.items||[];const layout=el('div',null,'details-grid'),list=el('div',null,'select-list'),editor=el('div',null,'stack');\n const kind=el('select');for(const [v,t] of [['announcement','공지사항'],['release','업데이트 내역']]){const o=el('option',t);o.value=v;kind.append(o);}\n const state=el('select');for(const [v,t] of [['draft','임시저장'],['published','게시'],['archived','보관']]){const o=el('option',t);o.value=v;state.append(o);}\n const title=field('제목'),body=field('내용','','textarea');const labelFor=(label,node)=>append(el('label',null,'field'),el('span',label),node);\n const form=()=>{editor.replaceChildren(labelFor('구분',kind),labelFor('상태',state),title.outer,body.outer,el('p','최초 게시일 기준 7일(KST 경계) 후 공개 페이지에서 자동 비표시됩니다. 이후 내용을 수정해도 최초 게시일이 초기화되지 않습니다.','minor'),btn('저장',async()=>{\n  try{const current=items.find(x=>x.id===selected);const payload={kind:kind.value,state:state.value,title:title.input.value,body:body.input.value};\n   const path=current?'/api/admin/publications/'+encodeURIComponent(current.id):'/api/admin/publications';\n   await request(path,{method:current?'PATCH':'POST',body:JSON.stringify(payload)});message('게시물 저장 완료');selected=null;await publications();}catch(e){message(e.message,true);}\n  },'primary'))};\n const select=item=>{selected=item?.id||null;kind.value=item?.kind||'announcement';state.value=item?.state||'draft';title.input.value=item?.title||'';body.input.value=item?.body||'';form();draw();};\n const draw=()=>{list.replaceChildren(btn('새 공지 / 업데이트 작성',()=>select(null),'primary'));items.forEach(item=>{const b=el('button',item.title);b.type='button';b.setAttribute('aria-pressed',String(selected===item.id));b.append(el('small',(item.kind==='release'?'업데이트':'공지')+' · '+item.state+' · '+dt(item.first_published_at)));b.addEventListener('click',()=>select(item));list.append(b);});};\n const current=items.find(x=>x.id===selected);select(current||null);layout.append(list,editor);root(box('공지·업데이트 편집',layout));}\n async function system(){const d=await request('/api/admin/system');root(box('운영 상태',line('서비스',d.service),line('Worker 요청',d.worker_status),line('D1 연결',d.d1_status),line('Git 커밋',fmt(d.git_sha)),line('배포 버전',fmt(d.worker_version)),line('배포 시각',fmt(d.last_deploy_at))),el('div','배포 메타데이터는 환경에 주입된 경우에만 표시합니다. Cloudflare 운영 버전과 별도 실측 일치 여부는 최종 배포 승인 때 검증해야 합니다.','notice'));}\n async function security(){const d=await request('/api/admin/security');const old=field('현재 비밀번호','','password'),next=field('신규 비밀번호 (14자 이상)','','password');const change=box('관리자 비밀번호 변경',old.outer,next.outer,btn('비밀번호 변경 후 전체 세션 종료',async()=>{\n  if(!confirm('비밀번호를 변경하면 모든 관리자 세션이 무효화됩니다. 진행할까요?'))return;\n  try{await request('/api/admin/password',{method:'POST',body:JSON.stringify({current_password:old.input.value,new_password:next.input.value})});window.location.href='/admin/login/';}catch(e){message(e.message,true);}\n },'primary'));\n const stats=box('접근 제어 현황',line('현재 유효한 로그인 세션',d.active_sessions),line('일시 차단된 로그인 출처',d.locked_subjects));\n const retention=box('데이터 보존',el('p','변환 진단 이벤트는 30일, 처리 완료 후 90일을 넘긴 문의는 정리합니다. 문서 내용은 수집하지 않습니다.','minor'),btn('30일 초과 진단 이벤트 정리',async()=>{if(!confirm('보존기간이 지난 이벤트를 삭제할까요?'))return;try{await request('/api/admin/retention/purge',{method:'POST'});message('30일 초과 이벤트 정리 완료');}catch(e){message(e.message,true);}}));\n const revoke=box('세션 강제 종료',btn('모든 관리자 세션 무효화',async()=>{if(!confirm('모든 관리자 세션을 종료할까요?'))return;try{await request('/api/admin/sessions/revoke-all',{method:'POST'});window.location.href='/admin/login/';}catch(e){message(e.message,true);}}));\n root(stats,revoke,change,retention,box('관리 작업 감사 기록',table(['시각(KST)','작업','유형','결과'],(d.audit||[]).map(x=>[dt(x.occurred_at),x.action,x.subject_type||'—',x.outcome]))));}\n const pages={overview,visits,diagnostics,inquiries,publications,system,security};\n async function go(name,push=false){if(!pages[name])name='overview';page=name;selected=null;if(push)history.pushState({},'',`/admin/${name}/`);headline(name);\n  for(const a of document.querySelectorAll('[data-page]')){if(a.dataset.page===name)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}\n  $('side').classList.remove('open');$('menu-toggle').setAttribute('aria-expanded','false');message('');root(el('p','데이터를 읽는 중입니다.','subtle'));\n  try{await pages[name]();$('system-badge').textContent='운영 DB 연결';$('system-badge').classList.remove('bad');}\n  catch(e){root(el('div','관리 데이터 조회가 실패했습니다.','notice'));$('system-badge').textContent='조회 실패';$('system-badge').classList.add('bad');message(e.message,true);}\n }\n async function boot(){const isLogin=location.pathname.startsWith('/admin/login');\n  if(isLogin){$('login-screen').hidden=false;$('workspace').hidden=true;$('top-session').textContent='로그인 필요';return;}\n  try{const r=await request('/api/admin/session');csrf=r.csrf;$('login-screen').hidden=true;$('workspace').hidden=false;$('logout').hidden=false;$('top-session').textContent='관리자 인증됨';await go(location.pathname.split('/')[2]||'overview');}\n  catch{window.location.replace('/admin/login/');}\n }\n $('login-form').addEventListener('submit',async e=>{e.preventDefault();$('login-error').textContent='';\n  try{await request('/api/admin/login',{method:'POST',body:JSON.stringify({username:$('login-user').value,password:$('login-password').value})});$('login-password').value='';window.location.href='/admin/overview/';}\n  catch(e){$('login-error').textContent=e.message;}\n });\n $('logout').addEventListener('click',async()=>{try{await request('/api/admin/logout',{method:'POST'});}finally{window.location.href='/admin/login/';}});\n $('refresh').addEventListener('click',()=>go(page||'overview'));\n $('menu-toggle').addEventListener('click',()=>{const on=$('side').classList.toggle('open');$('menu-toggle').setAttribute('aria-expanded',String(on));});\n for(const a of document.querySelectorAll('[data-page]'))a.addEventListener('click',e=>{e.preventDefault();go(a.dataset.page,true);});\n window.addEventListener('popstate',()=>go(location.pathname.split('/')[2]||'overview'));\n boot();\n})();\n";
export const CONTACT_HTML = "<!doctype html><html lang=\"ko\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Sunrise PDF PRO · 문의</title><link rel=\"stylesheet\" href=\"/admin/static/admin.css\"><script src=\"/admin/static/public.js\" defer></script></head><body data-public=\"contact\"><header class=\"site-head\"><a class=\"brand\" href=\"/local/\"><span class=\"brand-mark\">S</span><b>SUNRISE PDF PRO</b></a><a href=\"/news/\">공지·업데이트</a></header><main class=\"login-wrap\"><form id=\"public-inquiry\" class=\"login-panel\"><h1>고객 문의</h1><p>오류가 발생한 단계와 오류 코드만 설명해 주세요. 문서 원문, 파일명, 주민등록번호 등 민감정보는 작성하지 마세요.</p><label>회신 이메일<input id=\"public-email\" type=\"email\" autocomplete=\"email\" required maxlength=\"160\"></label><label>제목<input id=\"public-subject\" required maxlength=\"120\"></label><label>문의 내용<textarea id=\"public-message\" required maxlength=\"3000\" rows=\"6\"></textarea></label><label class=\"honeypot\" hidden>회사 웹사이트<input id=\"company_website\" tabindex=\"-1\" autocomplete=\"off\"></label><button class=\"primary\" type=\"submit\">문의 접수</button><p id=\"public-status\" role=\"status\"></p></form></main></body></html>\n";
export const NEWS_HTML = "<!doctype html><html lang=\"ko\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Sunrise PDF PRO · 공지·업데이트</title><link rel=\"stylesheet\" href=\"/admin/static/admin.css\"><script src=\"/admin/static/public.js\" defer></script></head><body data-public=\"news\"><header class=\"site-head\"><a class=\"brand\" href=\"/local/\"><span class=\"brand-mark\">S</span><b>SUNRISE PDF PRO</b></a><a href=\"/contact/\">고객 문의</a></header><main class=\"content\"><div class=\"heading\"><div><span class=\"eyebrow\">NEWSROOM</span><h1>공지사항 · 업데이트</h1><p class=\"subtle\">최근 7일 이내 공개된 내용</p></div></div><div id=\"public-news\">확인 중</div></main></body></html>\n";
export const PUBLIC_JS = "'use strict';\n(()=>{\n const $=id=>document.getElementById(id);\n const mk=(tag,text,cls)=>{const e=document.createElement(tag);if(text!=null)e.textContent=String(text);if(cls)e.className=cls;return e;};\n if(document.body.dataset.public==='news'){\n  fetch('/api/public/updates',{cache:'no-store'}).then(async r=>{if(!r.ok)throw Error('공지 데이터 연결 실패: '+r.status);return r.json();}).then(data=>{\n   const target=$('public-news');target.replaceChildren();\n   for(const [key,title] of [['announcements','공지사항'],['releases','업데이트']]){\n    const section=mk('section',null,'panel');section.append(mk('h2',title));\n    if(!data[key]?.length)section.append(mk('p','최근 7일간 게시된 내용이 없습니다.','subtle'));\n    for(const n of data[key]||[]){const article=mk('article');article.append(mk('h3',n.title),mk('p',n.body),mk('small',new Date(n.first_published_at*1000).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul'})));section.append(article);}\n    target.append(section);\n   }\n  }).catch(e=>{$('public-news').textContent=e.message;});\n }\n if(document.body.dataset.public==='contact')$('public-inquiry').addEventListener('submit',async e=>{\n  e.preventDefault();$('public-status').textContent='접수 중...';\n  const body={email:$('public-email').value,subject:$('public-subject').value,message:$('public-message').value,company_website:$('company_website').value};\n  try{const r=await fetch('/api/public/inquiries',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(body)});\n   const json=await r.json();if(!r.ok)throw Error(json.error||'문의 접수 실패');$('public-status').textContent='문의가 접수됐습니다. 접수번호: '+json.reference;$('public-message').value='';}\n  catch(err){$('public-status').textContent='접수 실패: '+err.message;}\n });\n})();\n";
